import React, { useState, useMemo } from 'react';
import { Select, SelectOption } from '../../../../components/common/Select';
import { useResponsive } from '../../../../hooks/useResponsive';
import { useFormOptions } from '../../../../hooks/useFormOptions';
import styles from './TaskPoolFilters.module.css';

export interface TaskPoolFilterValues {
  priority: string;
  skills: string;
  deadline: string;
  sort: string;
  showMyCreated: boolean;
}

export interface TaskPoolFiltersProps {
  filters: TaskPoolFilterValues;
  onChange: (filters: TaskPoolFilterValues) => void;
}

export const TaskPoolFilters: React.FC<TaskPoolFiltersProps> = ({ filters, onChange }) => {
  const { isMobile } = useResponsive();
  const [isExpanded, setIsExpanded] = useState(false);
  const { taskPriorityOptions, taskSkillOptions, deadlineFilterOptions, taskSortOrderOptions } =
    useFormOptions('task-pool');

  const allPriorityOptions: SelectOption[] = useMemo(
    () => [{ value: 'all', label: 'Tất cả ưu tiên' }, ...taskPriorityOptions],
    [taskPriorityOptions]
  );

  const allSkillOptions: SelectOption[] = useMemo(
    () => [{ value: 'all', label: 'Tất cả kỹ năng' }, ...taskSkillOptions],
    [taskSkillOptions]
  );

  const allDeadlineOptions: SelectOption[] = useMemo(
    () => [{ value: 'all', label: 'Mọi thời hạn' }, ...deadlineFilterOptions],
    [deadlineFilterOptions]
  );

  // Count active filters (sort is always set, so exclude it)
  const activeFilterCount = useMemo(() => {
    let count = 0;
    if (filters.priority !== 'all') count++;
    if (filters.skills !== 'all')   count++;
    if (filters.deadline !== 'all') count++;
    if (filters.showMyCreated)      count++;
    return count;
  }, [filters]);

  const hasActiveFilters = activeFilterCount > 0;

  const handlePriorityChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    onChange({ ...filters, priority: e.target.value });
  };

  const handleSkillsChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    onChange({ ...filters, skills: e.target.value });
  };

  const handleDeadlineChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    onChange({ ...filters, deadline: e.target.value });
  };

  const handleSortChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    onChange({ ...filters, sort: e.target.value });
  };

  const handleMyCreatedChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onChange({ ...filters, showMyCreated: e.target.checked });
  };

  const handleClear = () => {
    onChange({ priority: 'all', skills: 'all', deadline: 'all', sort: filters.sort, showMyCreated: false });
    setIsExpanded(false);
  };

  const handleToggle = () => setIsExpanded((prev) => !prev);
  const handleClose  = () => setIsExpanded(false);

  // ─── Mobile ──────────────────────────────────────────────────────────────
  if (isMobile) {
    return (
      <>
        {isExpanded && <div className={styles.filterBackdrop} onClick={handleClose} />}
        <div className={styles.container}>
          <div className={styles.mobileHeader}>
            <div className={styles.title}>Kho Công Việc</div>

            <div className={styles.filterDropdownWrapper}>
              <button
                className={styles.filterToggle}
                onClick={handleToggle}
                aria-expanded={isExpanded}
                aria-label="Toggle filters"
                type="button"
              >
                <i className="fas fa-filter" />
                <span>Lọc</span>
                {activeFilterCount > 0 && (
                  <span className={styles.filterBadge}>{activeFilterCount}</span>
                )}
                <i className={`fas fa-chevron-${isExpanded ? 'up' : 'down'}`} />
              </button>

              {isExpanded && (
                <div className={styles.mobileFilters}>                  <label className={styles.myCreatedToggle}>
                    <input
                      type="checkbox"
                      checked={filters.showMyCreated}
                      onChange={handleMyCreatedChange}
                      className={styles.myCreatedCheckbox}
                    />
                    <i className="fas fa-pen"></i> Công việc tôi tạo
                  </label>                  <Select
                    value={filters.priority}
                    onChange={handlePriorityChange}
                    options={allPriorityOptions}
                    size="small"
                    fullWidth
                  />
                  <Select
                    value={filters.skills}
                    onChange={handleSkillsChange}
                    options={allSkillOptions}
                    size="small"
                    fullWidth
                  />
                  <Select
                    value={filters.deadline}
                    onChange={handleDeadlineChange}
                    options={allDeadlineOptions}
                    size="small"
                    fullWidth
                  />
                  <Select
                    value={filters.sort}
                    onChange={handleSortChange}
                    options={taskSortOrderOptions}
                    size="small"
                    fullWidth
                  />
                  {hasActiveFilters && (
                    <button
                      className={styles.clearFiltersButton}
                      onClick={handleClear}
                      type="button"
                    >
                      <i className="fas fa-times-circle" />
                      <span>Xóa bộ lọc</span>
                    </button>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      </>
    );
  }

  // ─── Desktop ─────────────────────────────────────────────────────────────
  return (
    <div className={styles.container}>
      <div className={styles.title}>Kho Công Việc</div>

      <div className={styles.filters}>
        <label className={styles.myCreatedToggle}>
          <input
            type="checkbox"
            checked={filters.showMyCreated}
            onChange={handleMyCreatedChange}
            className={styles.myCreatedCheckbox}
          />
          <i className="fas fa-pen"></i> Công việc tôi tạo
        </label>
        <Select
          value={filters.priority}
          onChange={handlePriorityChange}
          options={allPriorityOptions}
          size="small"
        />
        <Select
          value={filters.skills}
          onChange={handleSkillsChange}
          options={allSkillOptions}
          size="small"
        />
        <Select
          value={filters.deadline}
          onChange={handleDeadlineChange}
          options={allDeadlineOptions}
          size="small"
        />
        <Select
          value={filters.sort}
          onChange={handleSortChange}
          options={taskSortOrderOptions}
          size="small"
        />
        {hasActiveFilters && (
          <button
            className={styles.clearFiltersButtonDesktop}
            onClick={handleClear}
            type="button"
            title="Xóa bộ lọc"
          >
            <i className="fas fa-times-circle" />
            <span>Xóa bộ lọc</span>
          </button>
        )}
      </div>
    </div>
  );
};
