/**
 * useConversations — manages the conversation list for the Messages Inbox.
 *
 * - Fetches paged conversations from the BFF
 * - Subscribes to NewMessage SignalR events to update last message preview in real-time
 * - Persists selected conversation in Redux
 */
import { useCallback, useEffect } from 'react';
import { useAppDispatch, useAppSelector } from '../store/hooks';
import {
  fetchConversations,
  fetchMoreConversations,
  selectConversation,
  clearUnreadMessages,
  updateConversationPreview,
  clearSelectedConversation,
} from '../store/slices/messagesInboxSlice';
import { useSignalREvent, HubEvent, NewMessageEvent } from '../services/signalr';
import type { ConversationSummary } from '../services/message/conversationTypes';

export function useConversations() {
  const dispatch = useAppDispatch();
  const {
    conversations,
    totalCount,
    loading,
    hasMore,
    page,
    selectedEntityId,
    selectedEntityType,
    unreadMessageCount,
  } = useAppSelector((s) => s.messagesInbox);

  // Fetch on mount — also clears the unread badge
  useEffect(() => {
    const timer = setTimeout(() => {
      dispatch(fetchConversations());
      dispatch(clearUnreadMessages());
    }, 0);
    return () => clearTimeout(timer);
  }, [dispatch]);

  const reload = useCallback(() => {
    dispatch(fetchConversations());
  }, [dispatch]);

  const loadMore = useCallback(() => {
    if (!hasMore) return;
    dispatch(fetchMoreConversations({ page: page + 1 }));
  }, [dispatch, hasMore, page]);

  const selectConv = useCallback(
    (entityId: string, entityType: 'ticket' | 'task' | 'incident') => {
      dispatch(selectConversation({ entityId, entityType }));
    },
    [dispatch],
  );

  const clearSelection = useCallback(() => {
    dispatch(clearSelectedConversation());
  }, [dispatch]);

  const selectedConversation: ConversationSummary | null =
    conversations.find(
      (c) => c.entityId === selectedEntityId && c.entityType === selectedEntityType,
    ) ?? null;

  // Listen to NewMessage events → update conversation preview in real-time
  useSignalREvent(
    HubEvent.NewMessage,
    useCallback(
      (e: NewMessageEvent) => {
        if (e.message.type !== 'message') return; // only chat messages, not comments
        dispatch(
          updateConversationPreview({
            entityId:    e.entityId,
            entityType:  e.entityType,
            lastMessage: {
              content:   e.message.content,
              userName:  e.message.userName,
              createdAt: e.message.createdAt,
            },
          }),
        );
      },
      [dispatch],
    ),
  );

  return {
    conversations,
    totalCount,
    loading,
    hasMore,
    selectedEntityId,
    selectedEntityType,
    selectedConversation,
    unreadMessageCount,
    reload,
    loadMore,
    selectConv,
    clearSelection,
  };
}
