/**
 * Real BFF API calls for History endpoints.
 * Base route: /web-bff/api/v1/history
 */

import { apiClient } from '../api';
import { BffResponse, unwrap } from '../shared/bffEnvelope';
import type { HistoryItem, HistoryStats, HistoryFilters, HistoryExportOptions } from '../../models/History';
import type { PaginatedResponse } from '../../models/common';
import type { BffHistoryPagedDto, BffHistoryStatsDto, BffHistoryItemDto } from './responseModel';
import { mapBffHistoryItem, mapBffHistoryStats } from './mapper';

export const historyEndpoint = {
  /**
   * GET /history/me?domain=&type=&from=&to=&page=&pageSize=
   * Returns one page of the current user's activity history, newest first.
   */
  getHistory: async (
    filters?: HistoryFilters,
    page = 1,
    pageSize = 20,
  ): Promise<PaginatedResponse<HistoryItem>> => {
    const params = new URLSearchParams({
      page:     String(page),
      pageSize: String(pageSize),
    });
    if (filters?.type)            params.set('domain', filters.type);
    if (filters?.actionType)      params.set('type',   filters.actionType);
    if (filters?.dateRange?.from) params.set('from',   filters.dateRange.from.toISOString());
    if (filters?.dateRange?.to)   params.set('to',     filters.dateRange.to.toISOString());

    const res = await apiClient.get<BffResponse<BffHistoryPagedDto>>(`/history/me?${params}`);
    const dto = unwrap(res);
    const totalPages = dto.pageSize > 0 ? Math.ceil(dto.total / dto.pageSize) : 1;
    return {
      items:      dto.items.map(mapBffHistoryItem),
      total:      dto.total,
      page:       dto.page,
      pageSize:   dto.pageSize,
      totalPages,
    };
  },

  /**
   * GET /history/stats
   * Returns aggregate statistics for the current user's completed work.
   */
  getStats: async (): Promise<HistoryStats> => {
    const res = await apiClient.get<BffResponse<BffHistoryStatsDto>>('/history/stats');
    return mapBffHistoryStats(unwrap(res));
  },

  /**
   * Export report — generated client-side (no BFF export endpoint yet).
   * Falls back to returning an empty Blob of the requested MIME type.
   */
  exportReport: async (options: HistoryExportOptions): Promise<Blob> => {
    const mimeType = options.format === 'csv' ? 'text/csv' : 'application/pdf';
    return new Blob([''], { type: mimeType });
  },

  /**
   * GET /history/items/{id}
   * Looks up a single activity item by its ID (checked across both ticket and task activities).
   */
  getHistoryItem: async (id: string): Promise<HistoryItem | null> => {
    try {
      const res = await apiClient.get<BffResponse<BffHistoryItemDto>>(`/history/items/${id}`);
      return mapBffHistoryItem(unwrap(res));
    } catch {
      return null;
    }
  },
};
