import React, {
  useState,
  useEffect,
  useRef,
  useCallback,
} from 'react';
import { createPortal } from 'react-dom';
import { incidentLocationService, IncidentLocationDto } from '../../../services/incidentLocations';
import styles from './IncidentLocationSearchInput.module.css';

// ─── Add-New Modal ─────────────────────────────────────────────────────────────

interface AddNewModalProps {
  initialName: string;
  onConfirm: (name: string, type: string) => void;
  onCancel: () => void;
  saving: boolean;
}

const TYPE_OPTIONS = [
  { value: 'room',              label: 'Phòng',   icon: 'fas fa-door-open' },
  { value: 'specific_location', label: 'Vị trí', icon: 'fas fa-map-marker-alt' },
];

const AddNewModal: React.FC<AddNewModalProps> = ({ initialName, onConfirm, onCancel, saving }) => {
  const [name, setName] = useState(initialName);
  const [type, setType] = useState('room');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;
    onConfirm(name.trim(), type);
  };

  return createPortal(
    <div className={styles.modalOverlay} onClick={onCancel}>
      <div className={styles.modal} onClick={(e) => e.stopPropagation()}>
        <div className={styles.modalHeader}>
          <span className={styles.modalTitle}>
            <i className="fas fa-plus-circle" /> Thêm phòng/ vị trí mới
          </span>
          <button type="button" className={styles.modalClose} onClick={onCancel}>✕</button>
        </div>

        <form onSubmit={handleSubmit}>
          <div className={styles.modalBody}>
            <div className={styles.modalField}>
              <label className={styles.modalLabel}>
                Tên phòng/ vị trí <span className={styles.required}>*</span>
              </label>
              <input
                type="text"
                className={styles.modalInput}
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="Nhập tên phòng/ vị trí..."
                autoFocus
                required
              />
            </div>

            <div className={styles.modalField}>
              <label className={styles.modalLabel}>
                Loại <span className={styles.required}>*</span>
              </label>
              <div className={styles.typeGrid}>
                {TYPE_OPTIONS.map((opt) => (
                  <button
                    key={opt.value}
                    type="button"
                    className={`${styles.typeCard} ${type === opt.value ? styles.typeCardActive : ''}`}
                    onClick={() => setType(opt.value)}
                  >
                    <i className={opt.icon} />
                    <span>{opt.label}</span>
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className={styles.modalFooter}>
            <button type="button" className={styles.btnCancel} onClick={onCancel} disabled={saving}>
              Huỷ
            </button>
            <button type="submit" className={styles.btnConfirm} disabled={saving || !name.trim()}>
              {saving
                ? <><i className="fas fa-spinner fa-spin" /> Đang lưu...</>
                : <><i className="fas fa-check" /> Thêm</>}
            </button>
          </div>
        </form>
      </div>
    </div>,
    document.body
  );
};

// ─── Portal dropdown ───────────────────────────────────────────────────────────

interface DropdownPortalProps {
  anchorRef: React.RefObject<HTMLDivElement | null>;
  dropdownRef: React.RefObject<HTMLDivElement | null>;
  children: React.ReactNode;
}

const DropdownPortal: React.FC<DropdownPortalProps> = ({ anchorRef, dropdownRef, children }) => {
  const [style, setStyle] = useState<React.CSSProperties>({});

  const reposition = useCallback(() => {
    const rect = anchorRef.current?.getBoundingClientRect();
    if (!rect) return;
    setStyle({
      position: 'fixed',
      top:      rect.bottom + 2,
      left:     rect.left,
      width:    rect.width,
      zIndex:   9999,
    });
  }, [anchorRef]);

  useEffect(() => {
    reposition();
    window.addEventListener('scroll', reposition, true);
    window.addEventListener('resize', reposition);
    return () => {
      window.removeEventListener('scroll', reposition, true);
      window.removeEventListener('resize', reposition);
    };
  }, [reposition]);

  return createPortal(
    <div ref={dropdownRef as React.RefObject<HTMLDivElement>} className={styles.dropdown} style={style}>
      {children}
    </div>,
    document.body
  );
};

// ─── Types ────────────────────────────────────────────────────────────────────

export type IncidentLocationMode =
  | 'department_room'    // Field 1: Khoa (from dept list) + Phòng/vị trí (searchable, addable)
  | 'specific_location'; // Field 2: Vị trí cụ thể (searchable, addable)

export interface IncidentLocationSearchInputProps {
  mode: IncidentLocationMode;
  value: string;
  onChange: (value: string) => void;
  label?: string;
  required?: boolean;
  disabled?: boolean;
  error?: string;
  placeholder?: string;
}

const PAGE_SIZE = 20;

// ─── Main component ────────────────────────────────────────────────────────────

export const IncidentLocationSearchInput: React.FC<IncidentLocationSearchInputProps> = ({
  mode,
  value,
  onChange,
  label,
  required = false,
  disabled = false,
  error,
  placeholder,
}) => {
  const [term, setTerm] = useState('');
  const [isOpen, setIsOpen] = useState(false);
  const [items, setItems] = useState<IncidentLocationDto[]>([]);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [loading, setLoading] = useState(false);
  const [initialized, setInitialized] = useState(false); // true once first fetch completes

  // Modal state
  const [showModal, setShowModal] = useState(false);
  const [modalInitialName, setModalInitialName] = useState('');
  const [isSaving, setIsSaving] = useState(false);

  const containerRef    = useRef<HTMLDivElement>(null);
  const inputWrapperRef = useRef<HTMLDivElement>(null);
  const sentinelRef     = useRef<HTMLDivElement>(null);
  const dropdownRef     = useRef<HTMLDivElement>(null);
  const searchTimer     = useRef<ReturnType<typeof setTimeout> | null>(null);

  const apiType = mode === 'specific_location' ? 'specific_location' : undefined; // undefined = no type filter = return all

  // ── Fetch ──────────────────────────────────────────────────────────────────
  const fetchLocations = useCallback(
    async (searchTerm: string, resetPage: boolean) => {
      setLoading(true);
      const nextPage = resetPage ? 1 : page + 1;
      try {
        const res = await incidentLocationService.search({
          search:   searchTerm || undefined,
          type:     apiType,
          page:     nextPage,
          pageSize: PAGE_SIZE,
        });
        setItems((prev) => (resetPage ? res.items : [...prev, ...res.items]));
        setPage(res.page);
        setTotalPages(res.totalPages);
      } catch {
        // silent
      } finally {
        setLoading(false);
        setInitialized(true);
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [page, apiType]
  );

  // Debounced search when term / open changes
  useEffect(() => {
    if (!isOpen) {
      setInitialized(false);
      return;
    }
    if (searchTimer.current) clearTimeout(searchTimer.current);
    searchTimer.current = setTimeout(() => {
      fetchLocations(term, true);
    }, 300);
    return () => {
      if (searchTimer.current) clearTimeout(searchTimer.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [term, isOpen]);

  // IntersectionObserver load-more
  useEffect(() => {
    if (!sentinelRef.current) return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0]?.isIntersecting && !loading && page < totalPages) {
          fetchLocations(term, false);
        }
      },
      { root: dropdownRef.current, threshold: 0.1 }
    );
    observer.observe(sentinelRef.current);
    return () => observer.disconnect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loading, page, totalPages, isOpen]);

  // Close dropdown on outside click
  useEffect(() => {
    const handler = (e: MouseEvent) => {
      const target = e.target as Node;
      const insideContainer = containerRef.current?.contains(target);
      const insideDropdown  = dropdownRef.current?.contains(target);
      if (!insideContainer && !insideDropdown) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  // ── Handlers ──────────────────────────────────────────────────────────────
  const handleTermChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    // If there was a selection, clear it so user can pick a new one
    if (value) onChange('');
    setTerm(e.target.value);
    setIsOpen(true);
  };

  const handleFocus = () => setIsOpen(true);

  // On blur: hide dropdown only if focus is not moving into dropdown
  const handleBlur = (e: React.FocusEvent<HTMLInputElement>) => {
    // relatedTarget: the element receiving focus (if any)
    const next = e.relatedTarget as Node | null;
    if (next && dropdownRef.current && dropdownRef.current.contains(next)) {
      // Focus is moving into dropdown (e.g. via Tab or click)
      return;
    }
    setIsOpen(false);
  };

  const handleSelectLocation = (item: IncidentLocationDto) => {
    onChange(item.name);
    setTerm('');
    setIsOpen(false);
  };

  const handleClear = () => {
    onChange('');
    setTerm('');
  };

  const handleOpenAddModal = () => {
    setModalInitialName(term.trim());
    setShowModal(true);
    setIsOpen(false);
  };

  const handleModalConfirm = async (name: string, type: string) => {
    setIsSaving(true);
    try {
      const created = await incidentLocationService.create(name, type);
      onChange(created.name);
      setTerm('');
      setShowModal(false);
    } catch {
      // silent
    } finally {
      setIsSaving(false);
    }
  };

  const hasSelection = !!value;

  // Partition unified results by type for grouped display
  const deptItems = items.filter((i) => i.type === 'department');
  const locItems  = items.filter((i) => i.type !== 'department');

  const noResults = !loading && items.length === 0;

  // Label for the locations section header
  const locSectionLabel = mode === 'department_room' ? 'Phòng / Vị trí' : 'Vị trí cụ thể';
  const locSectionIcon  = mode === 'department_room' ? 'fas fa-door-open' : 'fas fa-map-marker-alt';

  return (
    <>
      <div
        className={`${styles.container} ${error ? styles.hasError : ''} ${disabled ? styles.disabled : ''}`}
        ref={containerRef}
      >
        {label && (
          <label className={styles.label}>
            {label}
            {required && <span className={styles.required}> *</span>}
          </label>
        )}

        <div ref={inputWrapperRef} className={styles.inputWrapper}>
          <input
            type="text"
            className={styles.input}
            value={value && !term ? value : term}
            onChange={handleTermChange}
            onFocus={handleFocus}
            onBlur={handleBlur}
            placeholder={placeholder ?? (mode === 'department_room' ? 'Tìm khoa, phòng hoặc vị trí...' : 'Tìm vị trí cụ thể...')}
            disabled={disabled}
            required={required}
            autoComplete="off"
          />
          {hasSelection && !disabled && (
            <button
              type="button"
              className={styles.clearBtn}
              onClick={handleClear}
              title="Xoá lựa chọn"
            >
              ✕
            </button>
          )}
          {!hasSelection && (
            <span className={styles.searchIcon}>
              <i className="fas fa-search" />
            </span>
          )}
        </div>

        {error && <span className={styles.errorMsg}>{error}</span>}
      </div>

      {/* Portal dropdown — outside overflow:hidden parents */}
      {isOpen && !disabled && (
        <DropdownPortal anchorRef={inputWrapperRef} dropdownRef={dropdownRef}>
          {/* Initial loading state */}
          {!initialized ? (
            <div className={styles.loadingRow}>
              <i className="fas fa-spinner fa-spin" /> Đang tải...
            </div>
          ) : (
          <>
          {/* Departments section — only when mode=department_room */}
          {mode === 'department_room' && deptItems.length > 0 && (
            <>
              <div className={styles.sectionHeader}>
                <i className="fas fa-hospital" /> Khoa
              </div>
              {deptItems.map((d) => (
                <button
                  key={d.id}
                  type="button"
                  className={styles.item}
                  onClick={() => handleSelectLocation(d)}
                >
                  <span className={styles.itemType}>Khoa</span>
                  {d.name}
                </button>
              ))}
            </>
          )}

          {/* Rooms / locations */}
          {loading && items.length === 0 ? (
            <div className={styles.loadingRow}>
              <i className="fas fa-spinner fa-spin" /> Đang tải...
            </div>
          ) : (
            <>
              {locItems.length > 0 && (
                <>
                  <div className={styles.sectionHeader}>
                    <i className={locSectionIcon} />
                    {' '}{locSectionLabel}
                  </div>
                  {locItems.map((item) => (
                    <button
                      key={item.id}
                      type="button"
                      className={styles.item}
                      onClick={() => handleSelectLocation(item)}
                    >
                      <span className={styles.itemType}>
                        {item.type === 'room' ? 'Phòng' : 'Vị trí'}
                      </span>
                      {item.name}
                    </button>
                  ))}
                </>
              )}

              {page < totalPages && (
                <div ref={sentinelRef} className={styles.sentinel}>
                  {loading && (
                    <span className={styles.loadMoreHint}>
                      <i className="fas fa-spinner fa-spin" /> Đang tải thêm...
                    </span>
                  )}
                </div>
              )}
            </>
          )}

          {/* Empty state */}
          {noResults && (
            <div className={styles.emptyState}>
              <span>Không có bản ghi nào</span>
            </div>
          )}
          </>
          )}

          {/* Add new — always at bottom */}
          <button
            type="button"
            className={styles.addNewBtn}
            onClick={handleOpenAddModal}
          >
            <i className="fas fa-plus" />
            {term.trim() ? ` Thêm bản ghi "${term.trim()}"` : ' Thêm bản ghi mới'}
          </button>
        </DropdownPortal>
      )}

      {/* Add-New Modal */}
      {showModal && (
        <AddNewModal
          initialName={modalInitialName}
          onConfirm={handleModalConfirm}
          onCancel={() => setShowModal(false)}
          saving={isSaving}
        />
      )}
    </>
  );
};
