import { TicketStatus } from '../models/Ticket';

/**
 * Get Vietnamese label for ticket status
 */
export const getStatusLabel = (status: string | TicketStatus): string => {
  const statusLower = typeof status === 'string' ? status.toLowerCase() : status;
  
  switch (statusLower) {
    case 'new':
    case TicketStatus.New:
      return 'Mới';
    case 'submitted':
    case TicketStatus.Submitted:
      return 'Đã Gửi';
    case 'pending':
    case TicketStatus.Pending:
      return 'Chờ Thông Tin';
    case 'triaged':
    case TicketStatus.Triaged:
      return 'Đã Duyệt';
    case 'rejected':
    case TicketStatus.Rejected:
      return 'Từ Chối';
    case 'assigned':
    case TicketStatus.Assigned:
      return 'Đã Phân Công';
    case 'in_progress':
    case TicketStatus.InProgress:
      return 'Đang Xử Lý';
    case 'help_requested':
    case TicketStatus.HelpRequested:
      return 'Yêu Cầu Hỗ Trợ';
    case 'support_assigned':
    case TicketStatus.SupportAssigned:
      return 'Đã Phân Công Hỗ Trợ';
    case 'blocked':
    case TicketStatus.Blocked:
      return 'Bị Chặn';
    case 'resolved':
    case TicketStatus.Resolved:
      return 'Đã hoàn thành';
    case 'approved':
    case TicketStatus.Approved:
      return 'Đã Chấp Thuận';
    case 'reopened':
    case TicketStatus.Reopened:
      return 'Mở Lại';
    case 'closed':
    case TicketStatus.Closed:
      return 'Đã Đóng';
    default:
      return status as string;
  }
};

/**
 * Get CSS class name for ticket status badge
 */
export const getStatusClassName = (status: string | TicketStatus): string => {
  const statusStr = typeof status === 'string' ? status : String(status);
  const statusLower = statusStr.toLowerCase().replace(/_/g, '-');
  return `status-${statusLower}`;
};

/**
 * Valid status transitions map for workflow validation
 */
export const VALID_STATUS_TRANSITIONS: Record<TicketStatus, TicketStatus[]> = {
  [TicketStatus.New]: [TicketStatus.Submitted],
  [TicketStatus.Submitted]: [TicketStatus.Triaged, TicketStatus.Rejected, TicketStatus.Pending],
  [TicketStatus.Pending]: [TicketStatus.Triaged, TicketStatus.Rejected],
  [TicketStatus.Triaged]: [TicketStatus.Assigned],
  [TicketStatus.Rejected]: [], // Terminal state
  [TicketStatus.Assigned]: [TicketStatus.InProgress],
  [TicketStatus.InProgress]: [TicketStatus.Blocked, TicketStatus.HelpRequested, TicketStatus.Resolved],
  [TicketStatus.HelpRequested]: [TicketStatus.SupportAssigned, TicketStatus.InProgress],
  [TicketStatus.SupportAssigned]: [TicketStatus.InProgress],
  [TicketStatus.Blocked]: [TicketStatus.InProgress],
  [TicketStatus.Resolved]: [TicketStatus.Approved, TicketStatus.Reopened],
  [TicketStatus.Approved]: [TicketStatus.Closed],
  [TicketStatus.Reopened]: [TicketStatus.InProgress],
  [TicketStatus.Closed]: [], // Terminal state
};

/**
 * Check if a status transition is valid
 */
export const isValidStatusTransition = (
  currentStatus: TicketStatus,
  newStatus: TicketStatus
): boolean => {
  const validTransitions = VALID_STATUS_TRANSITIONS[currentStatus] || [];
  return validTransitions.includes(newStatus);
};
