import React from 'react';
import { StatsCard, StatsCardsGrid } from '../../../../components/common';

export interface TaskPoolStats {
  total:    number;
  critical: number;
  high:     number;
  medium:   number;
  low:      number;
}

export interface TaskPoolStatsCardsProps {
  stats:         TaskPoolStats;
  loading?:      boolean;
  activeFilter?: string;   // 'all' | 'critical' | 'high' | 'medium' | 'low'
  onFilter?:     (priority: string) => void;
}

export const TaskPoolStatsCards: React.FC<TaskPoolStatsCardsProps> = ({
  stats,
  loading,
  activeFilter = 'all',
  onFilter,
}) => {
  const handleClick = (priority: string) => {
    if (!onFilter) return;
    // Toggle off if already active
    onFilter(activeFilter === priority ? 'all' : priority);
  };

  return (
    <StatsCardsGrid>
      <StatsCard
        label="Tất cả"
        value={stats.total}
        variant="total"
        loading={loading}
        active={activeFilter === 'all'}
        onClick={() => handleClick('all')}
      />
      <StatsCard
        label="Khẩn cấp"
        value={stats.critical}
        variant="danger"
        loading={loading}
        active={activeFilter === 'critical'}
        onClick={() => handleClick('critical')}
      />
      <StatsCard
        label="Cao"
        value={stats.high}
        variant="warning"
        loading={loading}
        active={activeFilter === 'high'}
        onClick={() => handleClick('high')}
      />
      <StatsCard
        label="Trung bình"
        value={stats.medium}
        variant="info"
        loading={loading}
        active={activeFilter === 'medium'}
        onClick={() => handleClick('medium')}
      />
      <StatsCard
        label="Thấp"
        value={stats.low}
        variant="success"
        loading={loading}
        active={activeFilter === 'low'}
        onClick={() => handleClick('low')}
      />
    </StatsCardsGrid>
  );
};
